UPDATE app_information_records SET values_json=json_set(
  CASE WHEN json_valid(values_json) THEN values_json ELSE '{}' END,
  '$.obyekt_nomi',COALESCE(json_extract(values_json,'$.obyekt_nomi'),json_extract(values_json,'$.obekt'),title),
  '$.pudrat_tashkiloti',COALESCE(json_extract(values_json,'$.pudrat_tashkiloti'),json_extract(values_json,'$.pudratchi')),
  '$.dastur_nomi',COALESCE(json_extract(values_json,'$.dastur_nomi'),json_extract(values_json,'$.dastur')),
  '$.obyekt_turi',COALESCE(json_extract(values_json,'$.obyekt_turi'),json_extract(values_json,'$.ish_turi')),
  '$.amalga_oshirish_muddati',COALESCE(json_extract(values_json,'$.amalga_oshirish_muddati'),json_extract(values_json,'$.boshlanish_tugash')),
  '$.obyekt_umumiy_qiymati',COALESCE(json_extract(values_json,'$.obyekt_umumiy_qiymati'),json_extract(values_json,'$.qiymat')),
  '$.hudud',json_extract(values_json,'$.hudud')
) WHERE template_id=(SELECT id FROM app_information_templates WHERE code='SRC_ROAD_NETWORK_DEVELOPMENT_DEVELOPMENT_PROGRAMS');
